diff --git a/proto/v2/entity.proto b/proto/v2/entity.proto
--- a/proto/v2/entity.proto
+++ b/proto/v2/entity.proto
@@ -3,5 +3,5 @@
 package simulation.v2;

 message Entity {
-  string entity_id = 1;
+  bytes entity_id = 1;
 }
diff --git a/runtimes/csharp/main.cs b/runtimes/csharp/main.cs
--- a/runtimes/csharp/main.cs
+++ b/runtimes/csharp/main.cs
@@ -18,7 +18,7 @@
     {
         var decoded = Simulation.V2.Entity.Parser.ParseFrom(rawBytes);
         entity = decoded;
-        fields = new() { ["entity_id"] = decoded.EntityId };
+        fields = new() { ["entity_id"] = System.Text.Encoding.UTF8.GetString(decoded.EntityId.ToByteArray()) };
     }
     else throw new ArgumentException($"Unsupported version: {version}");
     Console.WriteLine(JsonSerializer.Serialize(new { runtime = "csharp", version, fields }));
@@ -65,7 +65,7 @@
     var version = args.Contains("--v2") ? "v2" : "v1";
     IMessage entity = version == "v1"
