diff --git a/runtimes/python/main.py b/runtimes/python/main.py
--- a/runtimes/python/main.py
+++ b/runtimes/python/main.py
@@ -28,7 +28,7 @@
     if version not in ("v1", "v2"):
         raise ValueError(f"Unsupported schema version: {version}")
